sys_ui_context_menu.action_script:
var nsProTaskMain;

nsProTaskMain = parent.top.window.gsft_main;

setSelectedToRetired();

function setSelectedToRetired(){
	var selected;
	selected = g_list.getChecked();
	if(selected.length == 0)
	{
		selected = g_sysId;
	}
	//alert(selected);
	var circuit = new GlideAjax('x_g_sonc_ns_pro.circuit_ajax');
	circuit.addParam('sysparm_name', 'setSelectedCircuitsToRetired');
	circuit.addParam('sysparm_selectedCircuits', selected);
	circuit.getXMLAnswer(getResponse);

    function getResponse(response) {
		//alert(response);
        var responseObj = JSON.parse(response);
        if (responseObj.resultCode == 'success') {
			nsProTaskMain.g_form.addInfoMessage(response.message);
        } else {
            nsProTaskMain.g_form.addErrorMessage(response.message);
        }
        gsftSubmit(null, nsProTaskMain.g_form.getFormElement(), 'sysverb_update_and_stay');
    }

}

sys_ui_context_menu.on_show_script:
var nsProTaskMain;

nsProTaskMain = parent.top.window.gsft_main;

canbeRetired();

function canbeRetired() {

    var retire = false;

	var taskType;

	if(nsProTaskMain.g_form){

		taskType = nsProTaskMain.g_form.getValue('task_type');
	}

	var relatedListID = g_list.getRelated();



    if (taskType == 'terminate' && relatedListID == "REL:6be2fea4476dd61440fd43ff336d43ec") {
        retire = true;
    }

    if (retire) {
		g_menu.setVisible(g_item);
        g_menu.setEnabled(g_item);
        g_menu.setLabel(g_item, "<b style='color:tomato;'>• Set Circuits to Retired •</b>");

    } else {
		g_menu.setHidden(g_item);
        g_menu.setDisabled(g_item);
    }

}
